import {
  MeshNodeMaterial,
  PlaneGeometry,
  Mesh,
  Vector2,
  Group,
  Color,
} from 'three/webgpu';
import {
  texture,
  uv,
  normalLocal,
  uniform,
  mul,
  add,
  vec2,
  FloatNode,
} from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { imageUrl, depthMapUrl, scenePlacement } = config;
  const { x, y, z } = scenePlacement.position;
  const { x: rx, y: ry, z: rz } = scenePlacement.rotation;
  const { x: sx, y: sy, z: sz } = scenePlacement.scale;

  // Load textures
  const colorTex = ctx.textureLoader.load(imageUrl);
  const depthTex = ctx.textureLoader.load(depthMapUrl);

  // Tessellated plane
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // TSL nodes for displacement
  const mouseOffset = uniform(new Vector2(0, 0));
  const dispScale = uniform(0.05); // subtle displacement strength

  const depthSample = depthTex.sample(uv().add(mouseOffset));
  const displacement = depthSample.r.mul(dispScale);
  const positionNode = normalLocal.mul(displacement);

  // Material
  const material = new MeshNodeMaterial({
    colorNode: colorTex.sample(uv()),
    positionNode,
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.25,
    anisotropy: 0.5,
    side: 'double',
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(x, y, z);
  mesh.rotation.set(rx, ry, rz);
  mesh.scale.set(sx, sy, sz);

  const group = new Group();
  group.add(mesh);

  // Hover animation tracking
  const hoverTween = { current: null };

  // Pointer handler for parallax
  const updatePointer = (event) => {
    // Normalize pointer coordinates to [-1,1] relative to viewport
    const px = (event.clientX / window.innerWidth) * 2 - 1;
    const py = -(event.clientY / window.innerHeight) * 2 + 1;
    mouseOffset.value.set(px * 0.02, py * 0.02);
  };

  // Event handlers
  group.userData.handlers = {
    pointerenter: () => {
      gsap.killTweensOf(mesh.position);
      hoverTween.current = gsap.to(mesh.position, {
        y: 0.15,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto',
      });
    },
    pointerleave: () => {
      gsap.killTweensOf(mesh.position);
      hoverTween.current = gsap.to(mesh.position, {
        y: y,
        duration: 0.5,
        ease: 'power2.out',
        overwrite: 'auto',
      });
    },
    pointermove: updatePointer,
    click: () => {
      // Emit navigation event as specified
      if (ctx.emit) {
        ctx.emit('hub-features.select');
      }
    },
  };

  // Cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf(mesh.position);
    if (hoverTween.current) hoverTween.current.kill();
    geometry.dispose();
    material.dispose();
    // Textures are cached – do not dispose
  };

  return group;
}
